jobs.text:
wrap.appendChild(grid);
/* ── 练手局（bf-12）：门槛卡死时的出口 ────────────────────────────────
   用户实测：「好感必须 20~79 且当天没送过，否则 9 张卡全灰」→ 没法试玩。
   所以正式那 9 张卡之外，再恒定给一排练手入口：任意角色都能开局，
   **不结算好感、不计每日一次、不写 S.breakfastDay**（规则层 finish() 把 bondDelta 归零
   并打 practice 标；页面层 bfApplyResult 再跳过落账）。
   ⚠ 两个类名都是刻意选的，别改成既有类：
     · 不用 .bf-card —— tools/bf/headless.js 断言正式卡恰好 9 张；
     · 不用 .bf-btn  —— tools/e2e/bf.js 用 #bfPickHost .bf-btn 的第一个当「先不做了」。 */
if (opts.onPracticePick) {
  var pbox = el("div", "bf-tp-practice");
  pbox.style.cssText = "margin:2px 0 14px;padding:12px 14px;border:1px dashed #ffd76e;" +
    "border-radius:10px;background:rgba(255,215,110,.06)";
  pbox.appendChild(el("div", "bf-tp-pt", "🎯 <b>练手局 · 不影响好感</b>"));
  var psub = el("div", "bf-tp-psub",
    "上面 9 张受「好感 20~79 且今天没送过」限制；这一排不受任何限制 —— " +
    "任意角色都能开局练手，不结算好感、不计每日一次、不写「今天已送」。");
  psub.style.cssText = "font-size:13px;color:#b9a6c2;line-height:1.7;margin:5px 0 9px";
  pbox.appendChild(psub);
  var prow = el("div", "bf-tp-prow");
  prow.style.cssText = "display:flex;flex-wrap:wrap;gap:8px";
  for (var k = 0; k < list.length; k++) {
    (function (t) {
      var chip = doc.createElement("button");
      chip.type = "button";
      chip.className = "bf-pchip";
      chip.innerHTML = (t.f || "🙂") + " " + escHtml(t.name);
      chip.setAttribute("data-practice", "1");
      chip.setAttribute("data-practice-id", t.id);
      chip.title = "练手局：以「" + t.name + "」为对象开一局（当前好感 " + t.bond + "，本局不结算）";
      chip.style.cssText = "font:inherit;font-size:14px;padding:7px 13px;cursor:pointer;border-radius:8px;" +
        "border:1px solid #ffd76e;color:#ffd76e;background:rgba(255,215,110,.10)";
      chip.addEventListener("click", function () { opts.onPracticePick({ id:t.id, name:t.name, bond:t.bond, f:t.f }); });
      prow.appendChild(chip);
    })(list[k]);
  }
  pbox.appendChild(prow);
  wrap.appendChild(pbox);
}
var row = el("div", "bf-row");
var cancel = mkBtn("先不做了");
